create table if not exists public.homes(id uuid primary key default gen_random_uuid(),address text not null unique,created_at timestamptz not null default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,home_id uuid not null references public.homes(id),full_name text not null,phone text not null,home_address text not null,entrance text,floor text,apartment text,show_phone boolean not null default false,show_entrance boolean not null default false,show_floor boolean not null default false,show_apartment boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.consent_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),document_version text not null,document_text text not null,accepted_at timestamptz not null default now());
create table if not exists public.vehicles(id uuid primary key default gen_random_uuid(),home_id uuid not null references public.homes(id) on delete cascade,owner_id uuid not null references public.profiles(id) on delete cascade,make text not null,model text not null,license_plate text not null,created_at timestamptz not null default now(),unique(home_id,license_plate),check(license_plate ~ '^[АВЕКМНОРСТУХABEKMHOPCTYX][0-9]{3}[АВЕКМНОРСТУХABEKMHOPCTYX]{2}[0-9]{2,3}$'));
create table if not exists public.chat_messages(id uuid primary key default gen_random_uuid(),home_id uuid not null references public.homes(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,recipient_id uuid references public.profiles(id) on delete cascade,body text not null check(char_length(body) between 1 and 2000),created_at timestamptz not null default now());
create index if not exists profiles_home_idx on public.profiles(home_id);create index if not exists vehicles_home_plate_idx on public.vehicles(home_id,license_plate);create index if not exists chat_home_time_idx on public.chat_messages(home_id,created_at desc);
create or replace function public.domchat_new_user() returns trigger language plpgsql security definer set search_path='' as $$ declare m jsonb:=new.raw_user_meta_data; addr text; hid uuid; begin if m->>'consent_accepted'<>'true' or coalesce(m->>'consent_text','')='' or coalesce(m->>'consent_version','')='' then raise exception 'Необходимо принять согласие на обработку персональных данных';end if;if coalesce(trim(m->>'full_name'),'')='' or coalesce(trim(m->>'phone'),'')='' or coalesce(trim(m->>'home_address'),'')='' then raise exception 'Заполните обязательные поля профиля';end if;addr:=regexp_replace(trim(m->>'home_address'),'\\s+',' ','g');insert into public.homes(address) values(addr) on conflict(address) do update set address=excluded.address returning id into hid;insert into public.profiles(id,home_id,full_name,phone,home_address,entrance,floor,apartment) values(new.id,hid,trim(m->>'full_name'),trim(m->>'phone'),addr,nullif(trim(m->>'entrance'),''),nullif(trim(m->>'floor'),''),nullif(trim(m->>'apartment'),''));insert into public.consent_records(user_id,document_version,document_text) values(new.id,m->>'consent_version',m->>'consent_text');return new;end $$;
drop trigger if exists domchat_auth_user on auth.users;create trigger domchat_auth_user after insert on auth.users for each row execute procedure public.domchat_new_user();
alter table public.homes enable row level security;alter table public.profiles enable row level security;alter table public.consent_records enable row level security;alter table public.vehicles enable row level security;alter table public.chat_messages enable row level security;
create policy "same home read" on public.homes for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.home_id=homes.id));
create policy "same home profiles" on public.profiles for select to authenticated using(home_id=(select home_id from public.profiles where id=auth.uid()));
create policy "own profile update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "own consent read" on public.consent_records for select to authenticated using(user_id=auth.uid());
create policy "same home vehicles read" on public.vehicles for select to authenticated using(home_id=(select home_id from public.profiles where id=auth.uid()));
create policy "own vehicles insert" on public.vehicles for insert to authenticated with check(owner_id=auth.uid() and home_id=(select home_id from public.profiles where id=auth.uid()));
create policy "own vehicles update" on public.vehicles for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid() and home_id=(select home_id from public.profiles where id=auth.uid()));
create policy "own vehicles delete" on public.vehicles for delete to authenticated using(owner_id=auth.uid());
create policy "same home chat read" on public.chat_messages for select to authenticated using(home_id=(select home_id from public.profiles where id=auth.uid()) and (recipient_id is null or sender_id=auth.uid() or recipient_id=auth.uid()));
create policy "same home chat insert" on public.chat_messages for insert to authenticated with check(sender_id=auth.uid() and home_id=(select home_id from public.profiles where id=auth.uid()) and (recipient_id is null or exists(select 1 from public.profiles r where r.id=recipient_id and r.home_id=chat_messages.home_id)));
create policy "own chat delete" on public.chat_messages for delete to authenticated using(sender_id=auth.uid());
do $$ begin alter publication supabase_realtime add table public.chat_messages;exception when duplicate_object then null;when undefined_object then null;end $$;